{
  "anomaly_detected": true,
  "confidence": 0.91,
  "anomalies": [
    {
      "category": "wrong_value",
      "components": ["R36"],
      "pins": ["R36.1", "R36.2"],
      "nets": ["VOUTN", "VOUTP"],
      "observed": "R36 is specified as 24k in the netlist, but its MPN is FRC0805J240TSD and its description identifies it as a 24Ω resistor. If the listed part is sourced, it is 1000 times lower than the schematic value.",
      "expected": "A 24kΩ part should be sourced to match the specified value. R36 is connected across VOUTN and VOUTP, so a 24Ω part would heavily load these rails.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(comp (ref \"R36\") (value \"24k\")"
        },
        {
          "source": "netlist",
          "quote": "(field (name \"MPN\") \"FRC0805J240TSD\")"
        },
        {
          "source": "netlist",
          "quote": "(field (name \"Description\") \" 125mW Thick Film Resistors 150V ±100ppm/℃ ±5% 24Ω 0805 Chip Resistor - Surface Mount ROHS\")"
        },
        {
          "source": "netlist",
          "quote": "(node (ref \"R36\") (pin \"1\") (pintype \"passive\")) (node (ref \"R36\") (pin \"2\") (pintype \"passive\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"VOUTN\") ... (node (ref \"R36\") (pin \"1\")) ... (net (name \"VOUTP\") ... (node (ref \"R36\") (pin \"2\"))"
        }
      ],
      "impact": "If assembly follows the listed MPN, the 24Ω resistor across VOUTP and VOUTN could draw excessive current, collapsing or overloading the output and potentially overheating or damaging R36 or upstream circuitry.",
      "confidence": 0.91
    }
  ],
  "summary": "R36’s schematic value is 24kΩ, but its MPN and description specify 24Ω. This sourcing mismatch could make the assembled board behave very differently by heavily loading the VOUTP–VOUTN output."
}

